import{_ as a,o as n,c as s,a4 as e}from"./chunks/framework.B-wJupoK.js";const o="/assets/fable-mythos-relationship.CF6a2Vw7.svg",r="/assets/article-image-01.C4A5okoI.png",l="/assets/article-image-04.DYLWnQgO.png",p="/assets/safety-classifier-flow.CLy42Q8p.svg",m=JSON.parse('{"title":"简单理解Claude 最新的Fable 5 和 Mythos 5","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/简单理解Claude 最新的Fable 5 和 Mythos 5/简单理解Claude 最新的Fable 5 和 Mythos 5.md","filePath":"AI人工智能/简单理解Claude 最新的Fable 5 和 Mythos 5/简单理解Claude 最新的Fable 5 和 Mythos 5.md","lastUpdated":1781056864000,"__rawMarkdown":"# 简单理解Claude 最新的Fable 5 和 Mythos 5\\n\\n> 原文：https://www.anthropic.com/news/claude-fable-5-mythos-5\\n\\nAnthropic 这次发布了两个新模型，名字叫 **Claude Fable 5** 和 **Claude Mythos 5**。\\n\\n我理解下来，**Fable 5 像是给大多数人用的版本**，**Mythos 5 则是给少数可信专业用户用的版本**。它们其实用的是同一个底层模型，只是开放范围和安全限制不一样。\\n\\n![Fable 5 与 Mythos 5 的关系示意](./assets/fable-mythos-relationship.svg)\\n\\n## 它到底强在哪里\\n\\n这篇文章最想表达的是：**这个新模型真的很强，但也因为太强，所以必须加上更多安全限制。**\\n\\nFable 5 在**写代码、读文档、看图、做研究、处理长任务**这些方面都比以前的 Claude 更厉害。\\n\\n比如原文提到，它能处理很大的代码库，还能把原本**几个月的工程任务压缩到几天**。它也能看复杂图表，甚至只靠游戏画面玩完《Pokémon FireRed》。\\n\\n![Claude Fable 5 与 Mythos 5 的基准测试对比表](./assets/article-image-01.png)\\n\\n## 科学研究也变强了\\n\\n我觉得最有意思的是它在科学研究里的表现。\\n\\n**Mythos 5 可以帮助设计蛋白质、提出分子生物学假设，还能做一些基因组学研究。**\\n\\n比如在药物设计里，它能自己选择结合位点、运行工具、遇到失败后再调整。原文说，在 **14 个蛋白质靶点**里，有 **9 个**产生了值得继续研究的候选结果。\\n\\n![Mythos 5 设计的蛋白质复合体](./assets/article-image-04.png)\\n\\n## 为什么要加安全限制\\n\\n不过，**能力越强，风险也越大**。\\n\\n因为这种模型不只是能帮人写代码、做研究，也可能被坏人拿去做网络攻击，或者帮助完成危险的生物化学任务。\\n\\n所以 Anthropic 给 Fable 5 加了 **安全分类器**。简单说，就是先让另一个系统判断用户的问题有没有风险。\\n\\n如果问题涉及**网络安全、生物化学或模型蒸馏**，Fable 5 就不会直接回答，而是回退到能力稍弱一点的 **Opus 4.8**。\\n\\n![安全分类器工作流程](./assets/safety-classifier-flow.svg)\\n\\n这里有几个词需要解释一下：\\n\\n**分类器**就是判断问题类型的系统。  \\n**回退**就是换一个更安全的模型来回答。  \\n**越狱**就是有人故意用奇怪的提示词绕过安全限制。  \\n**模型蒸馏**就是用强模型生成大量内容，再训练另一个模型模仿它。\\n\\n## 谁能使用\\n\\n**Mythos 5 的限制会少一些，但不是谁都能用。**\\n\\n它主要开放给网络防御者、关键基础设施相关机构，以及未来一小部分生命科学研究者。普通用户用的是 **Fable 5**。\\n\\n两个模型价格一样：**输入每百万 token 10 美元，输出每百万 token 50 美元**。\\n\\n## 我的理解\\n\\n总的来说，我觉得这篇文章不是单纯在炫耀模型有多强，而是在说一个更现实的问题：\\n\\n**AI 越厉害，就越需要安全规则。**\\n\\nFable 5 代表普通人可以用到更强的 AI；Mythos 5 代表高风险能力只能给可信的人用。\\n\\n它们的重点不是“完全放开”，而是在**能力和安全之间找平衡**。\\n"}'),h={name:"AI人工智能/简单理解Claude 最新的Fable 5 和 Mythos 5/简单理解Claude 最新的Fable 5 和 Mythos 5.md"};function i(g,t,d,c,b,u){return n(),s("div",null,[...t[0]||(t[0]=[e("",32)])])}const y=a(h,[["render",i]]);export{m as __pageData,y as default};
